module tcp_segmenter(
    input clk,
    input reset,
    input enable,
    input [63:0] data_in,
    input [2:0] segment_size, // segment size in bytes (1 to 8)
    output reg [63:0] data_out,
    output reg output_valid
);
    reg [2:0] byte_counter;
    reg [63:0] internal_data;
    reg [2:0] total_segments;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_out <= 64'b0;
            output_valid <= 0;
            byte_counter <= 3'b0;
            internal_data <= 64'b0;
            total_segments <= 3'b0;
        end else if (enable) begin
            internal_data <= data_in;
            total_segments <= (64 / (segment_size * 8)); // Calculate total segments
            byte_counter <= 0;
            output_valid <= 1;
        end else if (output_valid) begin
            if (byte_counter < total_segments) begin
                data_out <= internal_data >> (byte_counter * (segment_size * 8));
                byte_counter <= byte_counter + 1;
            end else begin
                output_valid <= 0; // No more segments to output
            end
        end
    end
endmodule

