code:
module i2c_controller (
    input clk,
    input start,
    input [7:0] data_in,
    output reg scl,
    output reg sda,
    output reg ready
);
    reg [3:0] state;
    reg [7:0] address;
    reg [7:0] data;
    parameter IDLE = 4'b0000,
              START = 4'b0001,
              SEND_ADDRESS = 4'b0010,
              SEND_DATA = 4'b0011,
              STOP = 4'b0100;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                ready <= 1;
                if (start) begin
                    state <= START;
                    ready <= 0;
                end
            end
            START: begin
                sda <= 0; // Start condition
                scl <= 1;
                state <= SEND_ADDRESS;
            end
            SEND_ADDRESS: begin
                sda <= address[7]; // Send MSB of address
                // Shift address bits
                address <= {address[6:0], 1'b0};
                // Transition scl for data valid
                scl <= 0;
                scl <= 1;
                if (address == 0) state <= SEND_DATA; // All address bits sent
            end
            SEND_DATA: begin
                sda <= data[7]; // Send MSB of data
                // Shift data bits
                data <= {data[6:0], 1'b0};
                scl <= 0;
                scl <= 1;
                if (data == 0) state <= STOP; // All data bits sent
            end
            STOP: begin
                sda <= 1; // Stop condition
                ready <= 1;
                state <= IDLE;
            end
        endcase
    end
endmodule

