module ButterworthFilter (
    input clk,
    input reset,
    input [15:0] sample_in,
    output reg [15:0] sample_out
);
    reg [15:0] state [0:4]; // Stage storage for filter
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sample_out <= 0;
            for (i = 0; i < 5; i = i + 1) begin
                state[i] <= 0;
            end
        end else begin
            // Shift the state and apply filter coefficients (for simplicity using fixed coefficients)
            sample_out <= (sample_in + state[0] + state[1] + state[2] + state[3]) >> 2; // Example averaging

            // Shift the input to the state
            for (i = 4; i > 0; i = i - 1) begin
                state[i] <= state[i-1];
            end
            state[0] <= sample_in;
        end
    end
endmodule

