module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg tx_done
);
    parameter BAUD_RATE_DIV = 104;  // Adjust according to your clock frequency
    reg [3:0] bit_index;
    reg [7:0] shift_reg;
    reg [6:0] baud_counter;
    reg sending;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1'b1;  // Idle state of UART
            tx_done <= 1'b0;
            baud_counter <= 0;
            bit_index <= 0;
            sending <= 1'b0;
        end else if (start && !sending) begin
            shift_reg <= data_in;
            bit_index <= 0;
            baud_counter <= 0;
            sending <= 1'b1;
            tx <= 1'b0;  // Start bit
            tx_done <= 1'b0;
        end else if (sending) begin
            if (baud_counter < BAUD_RATE_DIV) begin
                baud_counter <= baud_counter + 1;
            end else begin
                baud_counter <= 0;
                if (bit_index < 8) begin
                    tx <= shift_reg[bit_index];  // Send data bits
                    bit_index <= bit_index + 1;
                end else begin
                    tx <= 1'b1;  // Stop bit
                    tx_done <= 1'b1;  // Transmission completed
                    sending <= 1'b0;  // Stop sending
                end
            end
        end
    end
endmodule

