module floyd_warshall (
    input clk,
    input rst,
    input [15:0] edges, // 4x4 matrix flattened (16 bits for weights)
    output reg [15:0] shortest_paths // 4x4 matrix flattened
);
    reg [1:0] i, j, k;
    reg [3:0] weight;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shortest_paths <= edges; // Initialize shortest_paths to edges
            i <= 0;
            j <= 0;
            k <= 0;
        end else if (k < 4) begin
            if (i < 4) begin
                if (j < 4) begin
                    weight = shortest_paths[i*4 + j];
                    // Relaxation step
                    if (shortest_paths[i*4 + k] + shortest_paths[k*4 + j] < weight) begin
                        shortest_paths[i*4 + j] <= shortest_paths[i*4 + k] + shortest_paths[k*4 + j];
                    end
                    j <= j + 1;
                end else begin
                    j <= 0;
                    i <= i + 1;
                end
            end else begin
                i <= 0;
                k <= k + 1;
            end
        end
    end
endmodule

