module lms_filter(
    input clk,
    input rst,
    input [15:0] x,    // Input signal
    input [15:0] d,    // Desired signal
    output reg [15:0] y, // Filter output
    output reg [15:0] w0, // Weight coefficient
    output reg [15:0] w1  // Weight coefficient
);
    parameter STEP_SIZE = 16'h0001; // Learning rate

    reg [15:0] error; // Error signal
    reg [15:0] x_delayed; // Delayed input signal

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            w0 <= 16'h0000;
            w1 <= 16'h0000;
            y <= 16'h0000;
            x_delayed <= 16'h0000;
        end else begin
            x_delayed <= x;
            // Calculate the output
            y <= (w0 * x) + (w1 * x_delayed);
            // Calculate error
            error <= d - y;
            // Update weights
            w0 <= w0 + (STEP_SIZE * error * x);
            w1 <= w1 + (STEP_SIZE * error * x_delayed);
        end
    end
endmodule

