module i2c_master (
    input clk,
    input start,
    input [7:0] data,
    output reg SDA,
    output reg SCL
);
    reg [3:0] state;
    reg [3:0] bit_index;

    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter SEND = 4'b0010;
    parameter STOP = 4'b0011;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                SDA <= 1; // High idle
                SCL <= 1;
                if (start) begin
                    state <= START;
                end
            end
            START: begin
                SDA <= 0; // Start condition
                state <= SEND;
                bit_index <= 0;
            end
            SEND: begin
                SCL <= 0; // Prepare to send data
                SDA <= data[7 - bit_index]; // Send bit
                bit_index <= bit_index + 1;
                if (bit_index == 7) begin
                    state <= STOP;
                end
            end
            STOP: begin
                SCL <= 0;
                SDA <= 0; // Prepare for stop condition
                SCL <= 1; // Generate stop condition
                SDA <= 1; // Release SDA
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
endmodule

