module instruction_pipeline (
    input wire clk,
    input wire rst,
    input wire [4:0] instruction_in,
    output reg [4:0] result_out
);
    reg [4:0] fetch_stage;
    reg [4:0] decode_stage;
    reg [4:0] execute_stage;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            fetch_stage <= 5'b00000;
            decode_stage <= 5'b00000;
            execute_stage <= 5'b00000;
            result_out <= 5'b00000;
        end else begin
            fetch_stage <= instruction_in;
            decode_stage <= fetch_stage;
            execute_stage <= decode_stage;
            result_out <= execute_stage;
        end
    end
endmodule

