module fir_filter (
    input wire clk,
    input wire rst,
    input wire [15:0] x_in,
    output reg [15:0] y_out
);
    parameter N = 32;
    reg [15:0] h [0:N-1]; // Coefficients
    reg [15:0] x [0:N-1]; // Shift register for input samples
    integer i;

    initial begin
        // Initialize coefficients (example coefficients)
        h[0] = 16'h0001; h[1] = 16'h0001; h[2] = 16'h0001; h[3] = 16'h0001;
        h[4] = 16'h0001; h[5] = 16'h0001; h[6] = 16'h0001; h[7] = 16'h0001;
        h[8] = 16'h0001; h[9] = 16'h0001; h[10] = 16'h0001; h[11] = 16'h0001;
        h[12] = 16'h0001; h[13] = 16'h0001; h[14] = 16'h0001; h[15] = 16'h0001;
        h[16] = 16'h0001; h[17] = 16'h0001; h[18] = 16'h0001; h[19] = 16'h0001;
        h[20] = 16'h0001; h[21] = 16'h0001; h[22] = 16'h0001; h[23] = 16'h0001;
        h[24] = 16'h0001; h[25] = 16'h0001; h[26] = 16'h0001; h[27] = 16'h0001;
        h[28] = 16'h0001; h[29] = 16'h0001; h[30] = 16'h0001; h[31] = 16'h0001;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y_out <= 16'h0000;
            for (i = 0; i < N; i = i + 1) begin
                x[i] <= 16'h0000;
            end
        end else begin
            // Shift input samples
            for (i = N-1; i > 0; i = i - 1) begin
                x[i] <= x[i-1];
            end
            x[0] <= x_in;

            // Compute FIR output
            y_out <= 16'h0000; // Initialize output
            for (i = 0; i < N; i = i + 1) begin
                y_out <= y_out + (x[i] * h[i]);
            end
        end
    end
endmodule

