module divide_by_4 (
    input wire clk,
    input wire reset,
    input wire din,
    output reg dout
);
    reg [1:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 2'b00;
            dout <= 1'b0;
        end else begin
            counter <= counter + 1;
            if (counter == 2'b11) begin
                dout <= din;
            end
        end
    end
endmodule

