module NVMe_Controller (
    input wire clk,
    input wire reset,
    input wire start,
    output reg [1:0] status // 00: IDLE, 01: PROCESS, 10: DONE
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam PROCESS = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] current_state, next_state;

    // State transition
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (start)
                    next_state = PROCESS;
                else
                    next_state = IDLE;
            end
            PROCESS: begin
                // Simulate processing time
                next_state = DONE;
            end
            DONE: begin
                next_state = IDLE; // Return to IDLE after processing
            end
            default: next_state = IDLE;
        endcase
    end

    // Status output
    always @(*) begin
        case (current_state)
            IDLE: status = 2'b00;
            PROCESS: status = 2'b01;
            DONE: status = 2'b10;
            default: status = 2'b00;
        endcase
    end

endmodule

