    input wire [7:0] fractional_value,
    output reg clk_out
);
    reg [15:0] counter;
    reg [15:0] vco_divider;
    reg [15:0] phase_accumulator;

    always @(posedge clk_ref) begin
        // Phase accumulator to simulate the PLL behavior
        phase_accumulator <= phase_accumulator + fractional_value;

        // VCO divider logic
        vco_divider <= phase_accumulator >> 8; // Adjust the resolution

        // Output clock generation
        if (counter < vco_divider) begin
            clk_out <= 1;
        end else begin
            clk_out <= 0;
        end

        // Counter for clock cycles
        counter <= counter + 1;
    end
endmodule

