module CLA_4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);
    wire [3:0] P; // Propagate
    wire [3:0] G; // Generate
    wire [3:0] C; // Carry

    // Generate and Propagate calculations
    assign P = A ^ B; // Propagate
    assign G = A & B; // Generate

    // Carry calculations
    assign C[0] = G[0] | (P[0] & Cin);
    assign C[1] = G[1] | (P[1] & G[0]) | (P[1] & P[0] & Cin);
    assign C[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & P[0] & Cin);
    assign C[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & P[1] & P[0] & Cin);

    // Sum calculation
    assign S = P ^ {C[2:0], Cin};
    assign Cout = C[3];

endmodule

module carry_skip_adder (
    input [3:0] A,      // First operand
    input [3:0] B,      // Second operand
    input Cin,          // Carry input
    output [3:0] Sum,   // Sum output
    output Cout         // Carry output
);
    wire [3:0] G, P;    // Generate and Propagate
    wire [4:0] C;       // Carry (C[0] = Cin)

    assign G = A & B;   // Generate
    assign P = A ^ B;   // Propagate

    assign C[0] = Cin;
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & C[1]);
    assign C[3] = G[2] | (P[2] & C[2]);
    assign C[4] = G[3] | (P[3] & C[3]);

    assign Sum = P ^ C[3:0]; // Sum output
    assign Cout = C[4];       // Final carry output
endmodule

