module watchdog_timer #(parameter LIMIT = 5) (
    input clk,
    input reset,
    output reg timeout
);

reg [2:0] counter; // 3-bit counter to hold values from 0 to 7

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 0;
        timeout <= 0;
    end else begin
        if (counter < LIMIT) begin
            counter <= counter + 1;
            timeout <= 0;
        end else begin
            timeout <= 1; // Trigger timeout when counter reaches the limit
        end
    end
end

endmodule

