module SRAM8bit (  
    input wire [7:0] data_in,  
    input wire [2:0] addr,  
    input wire write_enable,  
    input wire read_enable,  
    output reg [7:0] data_out  
);  

    reg [7:0] memory [7:0];  

    always @(*) begin  
        if (read_enable)  
            data_out = memory[addr];  
        else  
            data_out = 8'bz;  
    end  

    always @(posedge write_enable) begin  
        memory[addr] <= data_in;  
    end  
