module serializer (
    input wire clk,
    input wire reset,
    input wire [7:0] parallel_in,
    output reg serial_out,
    output reg done
);
    reg [2:0] bit_counter; // 3 bits to count from 0 to 7
    reg [7:0] data;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_counter <= 3'b000;
            data <= 8'b0;
            serial_out <= 1'b0;
            done <= 1'b0;
        end else begin
            if (bit_counter < 3'b1000) begin // 0 to 7
                serial_out <= data[bit_counter];
                bit_counter <= bit_counter + 1;
                done <= 1'b0;
            end else begin
                done <= 1'b1; // serialization complete
            end
        end
    end

    always @(posedge clk) begin
        if (bit_counter == 3'b000) begin
            data <= parallel_in; // load new data on first clock
        end
    end
endmodule

