module IIR_Filter (
    input clk,
    input reset,
    input signed [15:0] x, // Input signal
    output reg signed [15:0] y // Output signal
);
    // Filter coefficients (example values)
    parameter signed [15:0] b0 = 16'h0A00; // b0 coefficient
    parameter signed [15:0] b1 = 16'h0500; // b1 coefficient
    parameter signed [15:0] b2 = 16'h0200; // b2 coefficient
    parameter signed [15:0] a1 = 16'hF700; // a1 coefficient
    parameter signed [15:0] a2 = 16'hF300; // a2 coefficient
    parameter signed [15:0] a3 = 16'hF200; // a3 coefficient
    parameter signed [15:0] a4 = 16'hF100; // a4 coefficient

    reg signed [15:0] x_delay[0:4]; // Delay line for input
    reg signed [15:0] y_delay[0:4]; // Delay line for output

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 16'h0000; // Reset output
            x_delay[0] <= 16'h0000;
            x_delay[1] <= 16'h0000;
            x_delay[2] <= 16'h0000;
            x_delay[3] <= 16'h0000;
            x_delay[4] <= 16'h0000;
            y_delay[0] <= 16'h0000;
            y_delay[1] <= 16'h0000;
            y_delay[2] <= 16'h0000;
            y_delay[3] <= 16'h0000;
            y_delay[4] <= 16'h0000;
        end else begin
            // Shift delays
            x_delay[4] <= x_delay[3];
            x_delay[3] <= x_delay[2];
            x_delay[2] <= x_delay[1];
            x_delay[1] <= x_delay[0];
            x_delay[0] <= x;

            y_delay[4] <= y_delay[3];
            y_delay[3] <= y_delay[2];
            y_delay[2] <= y_delay[1];
            y_delay[1] <= y_delay[0];

            // Calculate output
            y <= (b0 * x_delay[0] + b1 * x_delay[1] + b2 * x_delay[2] 
                 - a1 * y_delay[1] - a2 * y_delay[2] 
                 - a3 * y_delay[3] - a4 * y_delay[4]) >>> 15; // Normalize
            y_delay[0] <= y;
        end
    end
endmodule

