module carry_skip_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);
    wire [3:0] P, G; // Propagate and Generate signals
    wire [3:0] C;    // Carry signals

    // Generate and Propagate logic
    assign P = A ^ B; // Propagate
    assign G = A & B; // Generate

    // Carry signals calculation
    assign C[0] = G[0] | (P[0] & Cin);
    assign C[1] = G[1] | (P[1] & C[0]);
    assign C[2] = G[2] | (P[2] & C[1]);
    assign C[3] = G[3] | (P[3] & C[2]);

    // Sum calculation
    assign Sum = P ^ {C[2:0], Cin}; // Final sum

    // Final carry out
    assign Cout = C[3];

endmodule

module SPI_Master(  
    input clk,  
    input cs,  
    input [7:0] data_in,  
    output reg mosi,  
    output reg sck  
);  
    reg [3:0] bit_count;  
    reg [7:0] shift_reg;  
    reg sending;  

    always @(posedge clk or negedge cs) begin  
        if (!cs) begin  
            // When chip select is active, start sending data  
            shift_reg <= data_in;  
            bit_count <= 4'b0000;  
            sending <= 1;  
            sck <= 0;  
        end else if (sending) begin  
            // Send data on rising edge of SCK  
            if (bit_count < 8) begin  
                mosi <= shift_reg[7]; // Send the MSB first  
                shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left  
                sck <= ~sck; // Toggle clock  
                if (sck) bit_count <= bit_count + 1; // Increment bit count on clock high  
            end else begin  
                sending <= 0; // Stop sending after 8 bits  
                sck <= 0;  
            end  
        end  
    end  
endmodule

